// 2026-02-14 Generated by IBM Bob
/*
    Cleanup orphaned container images from local registry.

    This workflow follows the below steps:
        - Fetches manifest files from GitHub (ibmstorage/qe-ceph-manifest)
        - Parses YAML files for specified release and vendor
        - Queries local registry for current image state
        - Compares and identifies orphaned images (not in manifest)
        - Deletes orphaned images (if not DRY_RUN)
        - Triggers garbage collection to free disk space

    Target Repositories:
        - rh-stage/* (RedHat staging images)
        - ibm-stage/* (IBM staging images)

    Safety Features:
        - DRY_RUN enabled by default
        - Repository whitelist (only rh-stage, ibm-stage)
        - Safety threshold (aborts if >50% orphans without FORCE_CLEANUP)
        - Detailed logging and audit trail

    Scheduling:
        - Runs daily at 4 AM (after sync jobs complete)
        - Can be triggered manually
*/

def job = pipelineJob("cleanup-registry-images") {
    // Display name
    displayName("Infra - Cleanup Orphaned Registry Images")

    // Description
    description("""
        Cleans up orphaned container images from local registry.

        Compares registry state with qe-ceph-manifest and removes images
        that are not present in the manifest repository.

        Target repositories: rh-stage, ibm-stage

        Safety features:
        - DRY_RUN enabled by default
        - Safety threshold prevents mass deletion
        - Detailed reporting and audit trail

        Scheduled to run daily at 4 AM.
    """)

    definition {
        cpsScm {
            scm {
                git {
                    branch("*/main")
                    remote {
                        url("https://github.com/ibmstorage/ceph-qe-jenkins.git")
                        credentials("ceph-qe-sa-pat")
                    }
                }
            }
            scriptPath("jobs/pipelines/cleanup_registry_images/Jenkinsfile")
            lightweight(true)
        }
    }

    // Parameters
    parameters {
        booleanParam(
            "DRY_RUN",
            true,
            "If enabled, preview orphaned images without deleting them (RECOMMENDED for first run)"
        )
        booleanParam(
            "FORCE_CLEANUP",
            false,
            "Override safety threshold check (use with caution - only if >50% orphans is expected)"
        )
        booleanParam(
            "SKIP_GC",
            false,
            "Skip garbage collection after cleanup (for testing purposes)"
        )
    }

    // Triggers - scheduled daily at 4 AM
    triggers {
        cron('0 4 * * *')  // Daily at 4 AM (after sync jobs at 2 AM)
    }

    // Properties
    properties {
        buildDiscarder {
            strategy {
                logRotator {
                    artifactDaysToKeepStr("30")
                    artifactNumToKeepStr("10")
                    daysToKeepStr("30")
                    numToKeepStr("10")
                }
            }
        }
    }
}
